method derivative(xs: seq<int>) returns (result: seq<int>)
    requires |xs| > 0
    ensures |result| == |xs| - 1
    ensures result[i] == xs[i + 1] * (i + 1) | i in 0 .. |result| - 1
{
    var n := |xs|;

    // Initialize the result sequence
    result := new int[n - 1];

    // Compute the derivative
    var i := 0;
    while i < n - 1
        invariant 0 <= i <= n - 1
        invariant |result| == n - 1
    {
        result[i] := xs[i + 1] * (i + 1);
        i := i + 1;
    }
}
